 * AI Flow Page : https://github.com/nguyenquanicd/APB-CSR-Generator
 * Date         : 2026-10-28
 * Description  : Control and status registers with an APB4 slave interface.
 *                Clocks: one clock, i_clk_apb.
 *                Generated by APB-CSR-Generator v2.1; do not edit by hand.
 *                Source: sheet CRM_CSR of the CSR workbook.
 *                The RTL follows the VLSIT RTL Design Rule v2.
 */
`timescale 1ns/1ps

module m_vlsit_crmcsr #(
  localparam logic [31:0] LPARA_ADDR_W = 32'd16,
  localparam logic [31:0] LPARA_DATA_W = 32'd32,
  localparam logic [31:0] LPARA_STRB_W = 32'd4,
  localparam logic [31:0] LPARA_CLOCK_EN_OFFSET = 32'h0000,
  localparam logic [31:0] LPARA_CLOCK_DIV_OFFSET = 32'h0004
) (
  // APB clock and reset
  input  wire                     i_clk_apb,
  input  wire                     i_rst_n_apb,

  // APB slave interface
  input  wire                     i_apb_psel,
  input  wire                     i_apb_penable,
  input  wire                     i_apb_pwrite,
  input  wire  [LPARA_ADDR_W-1:0] i_apb_paddr,
  input  wire  [LPARA_DATA_W-1:0] i_apb_pwdata,
  input  wire  [LPARA_STRB_W-1:0] i_apb_pstrb,
  input  wire  [2:0]              i_apb_pprot,
  output logic                    o_apb_pready,
  output logic                    o_apb_pslverr,
  output logic [LPARA_DATA_W-1:0] o_apb_prdata,

  // Access check control
  input  wire                     i_protect_en,
  input  wire                     i_slverr_en,

  // Register clock_en
  output logic                    o_clock_en_en,

  // Register clock_div
  output logic [7:0]              o_clock_div_div
);

  // Internal signal declarations
  logic w_apb_setup;
  logic w_apb_prot_ok;
  logic w_apb_slverr;
  logic w_apb_complete;
  logic w_apb_wr;
  logic w_apb_rd;
  logic [LPARA_ADDR_W-1:0] reg_addr;
  logic [LPARA_DATA_W-1:0] reg_wdata;
  logic reg_slverr;
  logic w_rd_en;
  logic w_wr_en;
  logic [LPARA_DATA_W-1:0] w_rdata_nxt;
  logic reg_pready;
  logic [LPARA_DATA_W-1:0] reg_rdata;
  logic w_pready_nxt;
  logic reg_rd_capture;
  logic reg_wr_capture;
  logic w_we_clock_en;
  logic reg_clock_en_en;
  logic w_clock_en_en_nxt;
  logic [LPARA_DATA_W-1:0] w_clock_en_value;
  logic w_we_clock_div;
  logic [7:0] reg_clock_div_div;
  logic [7:0] w_clock_div_div_nxt;
  logic [LPARA_DATA_W-1:0] w_clock_div_value;

  // APB decode: the SETUP phase is PSEL high and PENABLE low and lasts one cycle per transfer.
  // A transfer is in error when the protection, the word alignment or the byte strobes fail
  // while i_slverr_en is 1.
  assign w_apb_setup    = i_apb_psel & ~i_apb_penable;
  assign w_apb_prot_ok  = i_protect_en ? ~i_apb_pprot[1] : 1'b1;
  assign w_apb_slverr   = i_slverr_en ? (~w_apb_prot_ok
                                         | (|i_apb_paddr[1:0])
                                         | (~&i_apb_pstrb & i_apb_pwrite)) : 1'b0;

  // Transfer without error, split into a write and a read.
  assign w_apb_complete = w_apb_setup & ~w_apb_slverr;
  assign w_apb_wr       = i_apb_pwrite & w_apb_complete;
  assign w_apb_rd       = ~i_apb_pwrite & w_apb_complete;

  // Address capture: holds the address of the last transfer without error.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_addr
    if (!i_rst_n_apb)
      reg_addr <= '0;
    else if (w_apb_complete)
      reg_addr <= i_apb_paddr;
  end

  // Write data capture: holds the data of the last write without error.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wdata
    if (!i_rst_n_apb)
      reg_wdata <= '0;
    else if (w_apb_wr)
      reg_wdata <= i_apb_pwdata;
  end

  // Error response flop: loaded in every SETUP phase while i_slverr_en is 1, and held otherwise.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_slverr
    if (!i_rst_n_apb)
      reg_slverr <= 1'b0;
    else if (w_apb_setup & i_slverr_en)
      reg_slverr <= w_apb_slverr;
  end

  // PSLVERR output follows the error response flop.
  assign o_apb_pslverr = reg_slverr;

  // Register write enables: a write enable of the captured address.
  assign w_we_clock_en = w_wr_en & (reg_addr == LPARA_CLOCK_EN_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_clock_div = w_wr_en & (reg_addr == LPARA_CLOCK_DIV_OFFSET[LPARA_ADDR_W-1:0]);

  // Read and write enables: the transfer without error, delayed by one cycle.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_capture
    if (!i_rst_n_apb) begin
      reg_rd_capture <= 1'b0;
      reg_wr_capture <= 1'b0;
    end else begin
      reg_rd_capture <= w_apb_rd;
      reg_wr_capture <= w_apb_wr;
    end
  end

  // Enables follow the capture flops.
  assign w_rd_en = reg_rd_capture;
  assign w_wr_en = reg_wr_capture;

  // PREADY next value: one cycle after the read or write enable, or after an error SETUP phase.
  assign w_pready_nxt = w_wr_en | w_rd_en | (w_apb_slverr & w_apb_setup);

  // PREADY flop: loaded with the next value, cleared by the reset.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_pready
    if (!i_rst_n_apb)
      reg_pready <= 1'b0;
    else
      reg_pready <= w_pready_nxt;
  end

  // PREADY output follows the PREADY flop.
  assign o_apb_pready = reg_pready;

  // clock_en_en next value (rw): a software write loads it, otherwise hold.
  assign w_clock_en_en_nxt = (w_we_clock_en) ? reg_wdata[0] : reg_clock_en_en;

  // Register clock_en: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_clock_en
    if (!i_rst_n_apb) begin
      reg_clock_en_en <= 1'h0;
    end else begin
      reg_clock_en_en <= w_clock_en_en_nxt;
    end
  end

  // Register clock_en: output ports follow the flops.
  assign o_clock_en_en = reg_clock_en_en;

  // Register clock_en: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_clock_en_value
    w_clock_en_value = '0;
    w_clock_en_value[0] = reg_clock_en_en;
  end

  // clock_div_div next value (rw): a software write loads it, otherwise hold.
  assign w_clock_div_div_nxt = (w_we_clock_div) ? reg_wdata[7:0] : reg_clock_div_div;

  // Register clock_div: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_clock_div
    if (!i_rst_n_apb) begin
      reg_clock_div_div <= 8'h0;
    end else begin
      reg_clock_div_div <= w_clock_div_div_nxt;
    end
  end

  // Register clock_div: output ports follow the flops.
  assign o_clock_div_div = reg_clock_div_div;

  // Register clock_div: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_clock_div_value
    w_clock_div_value = '0;
    w_clock_div_value[7:0] = reg_clock_div_div;
  end

  // Read data mux: value of the register at the captured address, 0 for any other address.
  always_comb begin : p_com_rdata
    w_rdata_nxt = '0;
    case (reg_addr)
      LPARA_CLOCK_EN_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_clock_en_value;
      LPARA_CLOCK_DIV_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_clock_div_value;
      default: w_rdata_nxt = '0;
    endcase
  end

  // Read data register, loaded by the read enable.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rdata
    if (!i_rst_n_apb)
      reg_rdata <= '0;
    else if (w_rd_en)
      reg_rdata <= w_rdata_nxt;
  end

  // PRDATA output follows the read data register.
  assign o_apb_prdata = reg_rdata;

endmodule
